# Call Julia's builtin flisp-based parser. `offset` is 0-based offset into the
# byte buffer or string.
function fl_parse(text::Union{Core.SimpleVector,String},
                  filename::String, lineno, offset, options, edition)
    if edition != FLISP_EDITION
        error("Edition $edition not supported by flisp parser (expected 1.14)")
    end
    if text isa Core.SimpleVector
        # Will be generated by C entry points jl_parse etc
        text, text_len = text
    else
        text_len = sizeof(text)
    end
    ccall(:jl_fl_parse, Any, (Ptr{UInt8}, Csize_t, Any, Csize_t, Csize_t, Any),
          text, text_len, filename, lineno, offset, options)
end

function fl_parse(text::AbstractString, filename::AbstractString, lineno,
                  offset, options, edition)
    fl_parse(String(text), String(filename), lineno, offset, options, edition)
end

function fl_lower(mod::Module, @nospecialize(ex), world::UInt, warn::Bool,
                  loc::LineNumberNode)
    ccall(:jl_fl_lower, Any, (Any, Any, Csize_t, Cint, Any),
          mod, ex, world, warn, loc)
end

# flisp lowering treats all syntax as FLISP_EDITION, so opt-in to flisp also
# opts out of editions >FLISP_EDITION.
function fl_toplevel_eval(mod::Module, @nospecialize(x))
    ex = if x isa Syntax
        Expr(:toplevel, first_linenode(x), syntax_to_expr(x))
    else
        x
    end
    ccall(:jl_toplevel_eval, Any, (Any, Any), mod, ex)
end
